add_expense:
function add_expense(amount, category, note) {
  if (typeof amount !== "number" || !isFinite(amount)) {
    throw new Error("amount must be a number");
  }
  if (amount <= 0) {
    throw new Error("amount must be greater than zero");
  }
  if (typeof category !== "string" || category.length === 0) {
    throw new Error("category must be a non-empty string");
  }
  if (note !== undefined && typeof note !== "string") {
    throw new Error("note must be a string");
  }
  state.expenses = state.expenses || [];
  var expense = { amount: amount, category: category };
  if (note !== undefined) {
    expense.note = note;
  }
  state.expenses.push(expense);
  return state.expenses.length;
}

total:
function total() {
  var expenses = state.expenses || [];
  var cents = 0;
  for (var i = 0; i < expenses.length; i++) {
    cents += expense_cents(expenses[i]);
  }
  return cents / 100;
}

by_category:
function by_category() {
  var expenses = state.expenses || [];
  var cents = {};
  for (var i = 0; i < expenses.length; i++) {
    var e = expenses[i];
    if (cents[e.category] === undefined) {
      cents[e.category] = 0;
    }
    cents[e.category] += expense_cents(e);
  }
  var sums = {};
  for (var key in cents) {
    if (Object.prototype.hasOwnProperty.call(cents, key)) {
      sums[key] = cents[key] / 100;
    }
  }
  return sums;
}

to_cents:
function to_cents(amount) {
  if (typeof amount !== "number" || !isFinite(amount)) {
    throw new Error("amount must be a number");
  }
  return Math.round(amount * 100);
}

expense_cents:
function expense_cents(expense) {
  if (!expense || typeof expense !== "object") {
    throw new Error("expense must be an object");
  }
  return to_cents(expense.amount);
}

set_budget:
function set_budget(category, amount) {
  state.budgets = state.budgets || {};
  state.budgets[category] = amount;
  return amount;
}

over_budget:
function over_budget() {
  var budgets = state.budgets || {};
  var expenses = state.expenses || [];
  var spent = {};
  for (var i = 0; i < expenses.length; i++) {
    var e = expenses[i];
    if (spent[e.category] === undefined) {
      spent[e.category] = 0;
    }
    spent[e.category] += expense_cents(e);
  }
  var over = [];
  for (var category in budgets) {
    if (!Object.prototype.hasOwnProperty.call(budgets, category)) {
      continue;
    }
    var spentCents = spent[category] === undefined ? 0 : spent[category];
    if (spentCents > to_cents(budgets[category])) {
      over.push(category);
    }
  }
  over.sort();
  return over;
}

top_category:
function top_category() {
  var expenses = state.expenses || [];
  var categories = [];
  var cents = {};
  for (var i = 0; i < expenses.length; i++) {
    var e = expenses[i];
    if (cents[e.category] === undefined) {
      cents[e.category] = 0;
      categories.push(e.category);
    }
    cents[e.category] += expense_cents(e);
  }
  if (categories.length === 0) {
    return null;
  }
  categories.sort();
  var best = categories[0];
  for (var j = 1; j < categories.length; j++) {
    if (cents[categories[j]] > cents[best]) {
      best = categories[j];
    }
  }
  return best;
}
